input.command:
duckdb << 'EOF'
-- q01: Count STAC Collections and find recommended collection
INSTALL json;
LOAD json;
INSTALL httpfs;
LOAD httpfs;

-- Read the TrazoFields catalog to find child collections
SELECT json_extract(
  read_text('https://data.source.coop/wri-data-lab/trazofields/catalog.json'),
  '$'
) as catalog_json;
EOF

