input.command:
duckdb << 'EOF'
-- q02: Row count per tier in facilities layer
INSTALL httpfs;
LOAD httpfs;
SELECT
  tier,
  COUNT(*) as n
FROM (
  SELECT tier FROM 'https://data.source.coop/tristangruppwri/soft-commodity-infrastructure/facilities/BR_facilities.parquet'
)
GROUP BY tier
ORDER BY tier;
EOF

duckdb << 'EOF'
-- q03: Row count and distinct cod_imovel in CAR
INSTALL httpfs;
LOAD httpfs;
SELECT
  COUNT(*) as n_rows,
  COUNT(DISTINCT cod_imovel) as n_distinct_ids
FROM 'https://data.source.coop/tristangruppwri/cadastral/brazil-car-area-imovel/brazil_car_area_imovel.parquet';
EOF

