duckdb << 'EOF' 2>&1
INSTALL httpfs;
LOAD httpfs;

-- Load fields and get bounding box analysis
SELECT COUNT(*) as n_fields_in_envelope
FROM 'https://data.source.coop/wri-data-lab/trazofields/trazo3-fields/trazo3_brazil_goias_2024.parquet' t;
EOF

duckdb << 'EOF' 2>&1
INSTALL spatial;
LOAD spatial;
INSTALL httpfs;
LOAD httpfs;

-- Get a sample field to check its size
SELECT 
    ST_Area(geometry) as area_degrees,
    ST_Area(geometry, true) as area_sqm
FROM 'https://data.source.coop/wri-data-lab/trazofields/trazo3-fields/trazo3_brazil_goias_2024.parquet'
LIMIT 1;
EOF

duckdb << 'EOF' 2>&1
INSTALL spatial;
LOAD spatial;
INSTALL httpfs;
LOAD httpfs;

-- Calculate proper area in hectares for matched fields
-- Using spherical area function if available or approximation
SELECT 
    COUNT(*) as n_fields,
    ROUND(SUM(ST_Area(geometry)) * 10.09 / 10000, 2) as estimated_ha
FROM 'https://data.source.coop/wri-data-lab/trazofields/trazo3-fields/trazo3_brazil_goias_2024.parquet'
LIMIT 1;
EOF

